 public void selectPhone(String phone){Phone f=phones.get(phone);if(f==null||SystemClock.elapsedRealtime()-f.seen>12000){linkInfo="手機已離線，請重新搜尋";return;}if(!p.getString("secret."+phone,"").isEmpty()){linkInfo="此手機已配對，可在手機開啟控制";return;}if(parentCount()>=8){linkInfo="最多可配對8位家長";return;}openPairing();selectedPhone=phone;invite=Crypto.token();linkInfo="已邀請 "+f.name+"，請在家長手機確認連線";}
 static volatile TvService instance;static volatile String linkInfo="正在搜尋家長手機";static volatile String pairCode="";static volatile boolean pairDialog=false;
 android.content.SharedPreferences p,learning;Handler h=new Handler();NsdManager nsd;NsdManager.DiscoveryListener discovery;WifiManager.MulticastLock multicast;WindowManager wm;volatile View overlay;volatile boolean running;volatile String host="";volatile int port=0;volatile long pairingUntil=0;long lastTry=0;int attempts=0;KeyPair keyPair;String id;BroadcastReceiver screen;
