 public void onCreate(){super.onCreate();instance=this;p=getSharedPreferences("control",0);learning=getSharedPreferences("learning",0);SettingsMigration.upgrade(learning);id=p.getString("id","");if(id.isEmpty()){id=UUID.randomUUID().toString();p.edit().putString("id",id).commit();}foreground();wm=(WindowManager)getSystemService(WINDOW_SERVICE);media=new MediaGate(this,p);sounds=new QuizSound(this,p);studyHistory=new LearningHistory(this);voiceClips=new OfflineVoice(this);appearanceListener=(prefs,key)->{if(key.equals("skin"))h.post(()->{if(overlay!=null)Skin.restyle(overlay);MainActivity a=MainActivity.active;if(a!=null&&a.inForeground)Skin.restyle(a.getWindow().getDecorView());});};getSharedPreferences("appearance",0).registerOnSharedPreferenceChangeListener(appearanceListener);running=true;
 int boot=Settings.Global.getInt(getContentResolver(),"boot_count",-1);if(Rules.rebootLock(p.getBoolean("timer",false),p.getInt("timerBoot",-2),boot))p.edit().putBoolean("timer",false).putBoolean("locked",true).commit();
 try{KeyFactory f=KeyFactory.getInstance("RSA");if(p.contains("private"))keyPair=new KeyPair(f.generatePublic(new X509EncodedKeySpec(Crypto.bytes(p.getString("public","")))),f.generatePrivate(new PKCS8EncodedKeySpec(Crypto.bytes(p.getString("private","")))));else{KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);keyPair=g.generateKeyPair();p.edit().putString("private",Crypto.b64(keyPair.getPrivate().getEncoded())).putString("public",Crypto.b64(keyPair.getPublic().getEncoded())).commit();}}catch(Exception e){linkInfo="配對金鑰讀取失敗";}
 screen=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(Intent.ACTION_SCREEN_OFF.equals(i.getAction()))watchAnswerTimer.pause(SystemClock.elapsedRealtime());else if(overlayKind.equals("quiz"))watchAnswerTimer.resume(SystemClock.elapsedRealtime());checkTimer();syncOverlay();}};IntentFilter screenEvents=new IntentFilter(Intent.ACTION_SCREEN_ON);screenEvents.addAction(Intent.ACTION_SCREEN_OFF);registerReceiver(screen,screenEvents);if(!p.getString("secret","").isEmpty()&&!p.getString("phoneId","").isEmpty()&&!p.contains("secret."+p.getString("phoneId","")))p.edit().putString("secret."+p.getString("phoneId",""),p.getString("secret","")).putString("ack."+p.getString("phoneId",""),p.getString("ack","")).commit();
 h.post(check);discover();new Thread(()->probeLoop(),"tv-lan-discovery").start();new Thread(()->pollLoop(),"tv-parent-link").start();}
 void foreground(){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel("control","家長控制服務",NotificationManager.IMPORTANCE_LOW));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"control"):new Notification.Builder(this);b.setContentTitle("邊看邊學兒童鎖").setContentText("家長連線與使用時間控制運作中").setSmallIcon(android.R.drawable.ic_lock_lock).setOngoing(true).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE));startForeground(2,b.build());}
 final ArrayDeque<NsdServiceInfo> resolveQueue=new ArrayDeque<NsdServiceInfo>();boolean resolving=false;
 void resolveNext(){if(resolving||resolveQueue.isEmpty()||!running)return;resolving=true;NsdServiceInfo service=resolveQueue.remove();try{nsd.resolveService(service,new NsdManager.ResolveListener(){public void onResolveFailed(NsdServiceInfo n,int error){h.post(()->{resolving=false;resolveNext();});}public void onServiceResolved(NsdServiceInfo n){if(n.getHost()!=null&&n.getPort()>0&&found.size()<24)found.put(n.getServiceName(),new InetSocketAddress(n.getHost(),n.getPort()));h.post(()->{resolving=false;resolveNext();});}});}catch(Exception e){resolving=false;h.post(()->resolveNext());}}
 void discover(){try{WifiManager wifi=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);if(wifi!=null&&multicast==null){multicast=wifi.createMulticastLock("learning-tv");multicast.setReferenceCounted(false);multicast.acquire();}nsd=(NsdManager)getSystemService(NSD_SERVICE);discovery=new NsdManager.DiscoveryListener(){public void onDiscoveryStarted(String t){}public void onDiscoveryStopped(String t){}public void onStartDiscoveryFailed(String t,int e){h.postDelayed(()->{if(running)discover();},15000);}public void onStopDiscoveryFailed(String t,int e){}public void onServiceLost(NsdServiceInfo s){found.remove(s.getServiceName());}public void onServiceFound(NsdServiceInfo s){h.post(()->{if(resolveQueue.size()<24){resolveQueue.add(s);resolveNext();}});}};nsd.discoverServices("_learnparent._tcp.",NsdManager.PROTOCOL_DNS_SD,discovery);}catch(Exception e){linkInfo="標準搜尋暫不可用，正使用區網備援搜尋";}}
 public int parentCount(){int n=0;for(String k:p.getAll().keySet())if(k.startsWith("secret."))n++;return n;}
 public void beginPairing(){openPairing();}
 void openPairing(){if(parentCount()>=8){linkInfo="最多可配對8位家長";return;}selectedPhone="";invite="";pairCode=String.format(java.util.Locale.US,"%06d",new SecureRandom().nextInt(1000000));pairingUntil=SystemClock.elapsedRealtime()+300000;attempts=0;linkInfo="新增家長配對開放5分鐘，請在手機選電視並輸入配對碼";MainActivity a=MainActivity.active;if(a!=null&&a.inForeground)a.parentPanel();}
 public void rescan(){selectedPhone="";invite="";openPairing();scanStarted=SystemClock.elapsedRealtime();linkInfo="正在自動搜尋家長手機（雙重搜尋）…";}
 void probeLoop(){while(running){try{probe=new DatagramSocket();probe.setBroadcast(true);probe.setSoTimeout(700);String nonce=UUID.randomUUID().toString();byte[] q=new JSONObject().put("type","learning-find-v1").put("nonce",nonce).toString().getBytes("UTF-8");for(InetAddress dest:LanDiscovery.broadcasts())try{probe.send(new DatagramPacket(q,q.length,dest,LanDiscovery.PORT));}catch(Exception ignored){}long until=SystemClock.elapsedRealtime()+2500;while(running&&SystemClock.elapsedRealtime()<until){try{byte[] bytes=new byte[2048];DatagramPacket packet=new DatagramPacket(bytes,bytes.length);probe.receive(packet);if(!LanDiscovery.privateV4(packet.getAddress()))continue;JSONObject r=new JSONObject(new String(bytes,0,packet.getLength(),"UTF-8"));int n=r.optInt("port");String phone=r.optString("phoneId");if(!"learning-parent-v1".equals(r.optString("type"))||!nonce.equals(r.optString("nonce"))||!phone.matches("[a-zA-Z0-9-]{1,64}")||n<1||n>65535)continue;String key="udp-"+phone;if(found.size()<24||found.containsKey(key)){found.put(key,new InetSocketAddress(packet.getAddress(),n));discoveredAt.put(key,SystemClock.elapsedRealtime());}}catch(SocketTimeoutException timeout){}}}catch(Exception ignored){}finally{if(probe!=null)probe.close();}try{Thread.sleep(1500);}catch(InterruptedException stop){break;}}}
 public void manual(String ip,int n)throws Exception{if(!ip.matches("[0-9]{1,3}(\\.[0-9]{1,3}){3}")||n<1||n>65535)throw new Exception("請確認 IPv4 位址與埠號");for(String part:ip.split("\\."))if(Integer.parseInt(part)>255)throw new Exception("IP 不正確");p.edit().putString("manualHost",ip).putInt("manualPort",n).apply();found.put("manual",new InetSocketAddress(ip,n));manualState="正在測試 "+ip+":"+n;linkInfo=manualState;}
 void pollLoop(){while(running){try{long now=SystemClock.elapsedRealtime();for(String key:discoveredAt.keySet())if(now-discoveredAt.get(key)>15000){found.remove(key);discoveredAt.remove(key);}Set<InetSocketAddress> candidates=new LinkedHashSet<InetSocketAddress>();String manual=p.getString("manualHost","");if(!manual.isEmpty())candidates.add(new InetSocketAddress(manual,p.getInt("manualPort",1)));candidates.addAll(found.values());int live=0;for(long seen:livePhones.values())if(now-seen<10000)live++;linkInfo="找到 "+candidates.size()+" 個連線位址 · 已配對 "+parentCount()+" 位家長 · 在線 "+live+" 位"+(pairingUntil>now?"\n配對碼："+pairCode+"（剩 "+((pairingUntil-now)/1000)+" 秒）":"")+(candidates.isEmpty()&&now-scanStarted>12000?"\n未找到手機：請開啟家長端並解鎖，確認同一Wi-Fi且非訪客網路。":"")+(manualState.isEmpty()?"":"\n"+manualState);
 for(InetSocketAddress endpoint:candidates){if(inFlight.size()>=12)break;String key=endpoint.toString();if(!inFlight.add(key))continue;linkPool.submit(()->{try{exchange(endpoint.getAddress()==null?endpoint.getHostString():endpoint.getAddress().getHostAddress(),endpoint.getPort());if(endpoint.getHostString().equals(p.getString("manualHost",""))&&endpoint.getPort()==p.getInt("manualPort",0))manualState="手動位址已連通";}catch(Exception e){if(endpoint.getHostString().equals(p.getString("manualHost",""))&&endpoint.getPort()==p.getInt("manualPort",0))manualState="手動連線失敗："+e.getClass().getSimpleName()+"；請確認IP、目前埠號及手機服務";}finally{inFlight.remove(key);}});}
 }catch(Exception ignored){}try{Thread.sleep(2000);}catch(InterruptedException stop){break;}}}
 void exchange(String address,int n)throws Exception{
 JSONObject hello=new JSONObject().put("id",id).put("type","hello").put("name",Build.MANUFACTURER+" "+Build.MODEL).put("pub",p.getString("public",""));if(!invite.isEmpty()&&SystemClock.elapsedRealtime()<pairingUntil)hello.put("invitePhone",selectedPhone).put("invite",invite);JSONObject greeting=Wire.call(address,n,hello);String phone=greeting.optString("phoneId");if(!phone.matches("[a-zA-Z0-9-]{1,64}"))throw new Exception("手機識別錯誤");Phone f=new Phone();f.id=phone;f.name=greeting.optString("phoneName","家長手機");f.address=address;f.port=n;f.seen=SystemClock.elapsedRealtime();f.modern=greeting.optInt("pairVersion")>=2;phones.put(phone,f);String secret=p.getString("secret."+phone,"");
 if(secret.isEmpty()){if(greeting.has("pair")&&SystemClock.elapsedRealtime()<pairingUntil&&attempts<5&&SystemClock.elapsedRealtime()-lastTry>3000){synchronized(this){if(pairDialog||SystemClock.elapsedRealtime()-lastTry<=3000)return;lastTry=SystemClock.elapsedRealtime();attempts++;pairDialog=true;}try{JSONObject data=Crypto.decrypt(keyPair.getPrivate(),greeting.getString("pair"));if(!pairAllowed(data,phone)||Crypto.bytes(data.getString("key")).length!=32)throw new Exception("配對碼錯誤");MainActivity a=MainActivity.active;if(a==null||!a.inForeground)throw new Exception("請開啟電視配對頁");h.post(()->{if(SystemClock.elapsedRealtime()>=pairingUntil){pairDialog=false;return;}new AlertDialog.Builder(a).setTitle("允許新增家長手機？").setMessage("手機識別："+phone.substring(0,8)+"\n請核對手機："+f.name+"\n允許後可控制此電視，其他家長仍保留。")
 .setPositiveButton("允許",(d,w)->{if(pairAllowed(data,phone)&&parentCount()<8){android.content.SharedPreferences.Editor edit=p.edit().putString("secret."+phone,data.optString("key"));if(p.getString("secret","").isEmpty())edit.putString("secret",data.optString("key")).putString("phoneId",phone).putString("recoveryHash",data.optString("recovery"));edit.commit();pairingUntil=0;pairCode="";selectedPhone="";invite="";}pairDialog=false;a.parentPanel();})
 .setNegativeButton("拒絕",(d,w)->{pairingUntil=0;pairCode="";selectedPhone="";invite="";pairDialog=false;}).setOnCancelListener(d->{pairingUntil=0;pairCode="";selectedPhone="";invite="";pairDialog=false;}).show();});}catch(Exception error){pairDialog=false;}}return;}
 String nonce=UUID.randomUUID().toString();JSONObject data=new JSONObject().put("nonce",nonce).put("ack",p.getString("ack."+phone,"")).put("name",Build.MANUFACTURER+" "+Build.MODEL).put("status",status());JSONObject request=new JSONObject().put("id",id).put("type","poll").put("data",Crypto.seal(secret,data));JSONObject response=Wire.call(address,n,request);if(!phone.equals(response.optString("phoneId")))throw new Exception("手機識別不符");JSONObject opened=Crypto.open(secret,response.getString("data"));if(!nonce.equals(opened.optString("nonce")))throw new Exception("replay");livePhones.put(phone,SystemClock.elapsedRealtime());if(opened.has("command")){JSONObject command=opened.getJSONObject("command");h.post(()->executeFrom(phone,command));}}
 boolean pairAllowed(JSONObject data,String phone){MainActivity a=MainActivity.active;return a!=null&&a.inForeground&&!p.getBoolean("locked",false)&&PairingRules.allowed(SystemClock.elapsedRealtime(),pairingUntil,pairCode,selectedPhone,invite,phone,data.optString("phone"),data.optString("pin"),data.optString("invite"));}
 void executeFrom(String phone,JSONObject c){String commandId=c.optString("id");if(commandId.isEmpty()||commandId.equals(p.getString("ack."+phone,"")))return;execute(c);p.edit().putString("ack."+phone,commandId).commit();}
 JSONObject status()throws Exception{JSONObject s=new JSONObject();s.put("homeMusic",p.getBoolean("homeMusic",true));s.put("parentCount",parentCount());s.put("skin",Skin.id(this));s.put("deviceModel",Build.MANUFACTURER+" "+Build.MODEL);s.put("androidVersion",Build.VERSION.RELEASE);s.put("sdk",Build.VERSION.SDK_INT);s.put("apps",videoApps());s.put("watchManaged",p.getBoolean("watchManaged",false));s.put("logicProgress",learning.getInt("logicCursor",0));s.put("logicLevels",new JSONArray(learning.getString("logicLevels",QuestionCatalog.DEFAULT_LEVELS)));s.put("watchEnabled",p.getBoolean("watchEnabled",false));s.put("watchPhase",watchPhase().name());s.put("watchRemaining",watchPhase()==WatchRules.Phase.WATCHING?Math.max(0,(p.getLong("rewardUntil",0)-SystemClock.elapsedRealtime()+999)/1000):0);s.put("rewardSeconds",p.getInt("rewardSeconds",30));s.put("mediaControl",media.info);s.put("watchCorrect",p.getInt("watchCorrect",0));s.put("watchAttempts",p.getInt("watchAttempts",0));s.put("locked",p.getBoolean("locked",false));s.put("remaining",p.getBoolean("timer",false)?Math.max(0,(p.getLong("deadlineElapsed",0)-SystemClock.elapsedRealtime()+999)/1000):-1);s.put("overlayPermission",Settings.canDrawOverlays(this));s.put("overlayVisible",overlay!=null);s.put("deviceOwner",owner());s.put("kioskActive",((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getLockTaskModeState()==ActivityManager.LOCK_TASK_MODE_LOCKED);s.put("result",p.getString("result","尚無"));s.put("correct",learning.getInt("liveCorrect",0));s.put("total",learning.getInt("liveTotal",0));return s;}

 public void prepareHomeProtection()throws Exception{if(!owner())throw new Exception("首頁鍵保護尚未設定：需先由家長完成此電視的 Device Owner 裝置管理設定。一般安裝或上層顯示權限無法封鎖首頁鍵。");DevicePolicyManager dpm=(DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE);ComponentName admin=new ComponentName(this,AdminReceiver.class);dpm.setLockTaskPackages(admin,new String[]{getPackageName()});if(Build.VERSION.SDK_INT>=28)dpm.setLockTaskFeatures(admin,DevicePolicyManager.LOCK_TASK_FEATURE_NONE);p.edit().putBoolean("strict",true).commit();}

 boolean owner(){return ((DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE)).isDeviceOwnerApp(getPackageName());}
 void execute(JSONObject c){String commandId=c.optString("id");if(commandId.isEmpty()||commandId.equals(p.getString("ack","")))return;try{String action=c.getString("action");JSONObject b=c.optJSONObject("payload");if(b==null)b=new JSONObject();switch(action){case "add_parent":openPairing();break;case "home_music":p.edit().putBoolean("homeMusic",b.getBoolean("enabled")).commit();if(MainActivity.active!=null)MainActivity.active.syncHomeMusic();break;case "skin":Skin.set(this,b.getString("id"));break;case "allow_home":unlock();startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));break;case "watch_start":startWatch(b);break;case "watch_stop":stopWatch();break;case "configure":configure(b);break;case "pause":if(MainActivity.active!=null&&MainActivity.active.inForeground&&MainActivity.active.playing)MainActivity.active.togglePause();else throw new Exception("請先在電視開始學習");break;case "timer":if(!Settings.canDrawOverlays(this)&&!(owner()&&p.getBoolean("strict",false)))throw new Exception("請先在電視授權上層顯示，或設定裝置管理");int minutes=b.getInt("minutes");if(minutes<1||minutes>1440)throw new Exception("時間範圍錯誤");if(p.getBoolean("locked",false))throw new Exception("目前已上鎖，請先由家長解鎖");p.edit().putBoolean("timer",true).putLong("deadlineElapsed",SystemClock.elapsedRealtime()+minutes*60000L).putLong("deadlineWall",System.currentTimeMillis()+minutes*60000L).putInt("timerBoot",Settings.Global.getInt(getContentResolver(),"boot_count",-1)).commit();break;case "lock":if(!Settings.canDrawOverlays(this)&&!(owner()&&p.getBoolean("strict",false)))throw new Exception("請先在電視授權上層顯示");lock();break;case "unlock":unlock();break;case "kiosk":if(p.getBoolean("watchEnabled",false))throw new Exception("答題換觀看模式需切換影音 App，不能同時啟用單一 App 嚴格鎖定");if(!owner())throw new Exception("尚未設為裝置擁有者，無法封住首頁鍵");DevicePolicyManager dpm=(DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE);dpm.setLockTaskPackages(new ComponentName(this,AdminReceiver.class),new String[]{getPackageName()});if(Build.VERSION.SDK_INT>=28)dpm.setLockTaskFeatures(new ComponentName(this,AdminReceiver.class),DevicePolicyManager.LOCK_TASK_FEATURE_NONE);p.edit().putBoolean("strict",true).commit();MainActivity a=MainActivity.active;if(a!=null&&a.inForeground)a.applyLockState();else throw new Exception("已設定；請在電視開啟邊看邊學以進入嚴格模式");break;default:throw new Exception("不支援此指令");}p.edit().putString("result","已完成："+actionName(action)).commit();}catch(Exception e){p.edit().putString("result","未完成："+e.getMessage()).commit();}p.edit().putString("ack",commandId).commit();}
 String actionName(String s){switch(s){case "add_parent":return "開放新增家長手機配對";case "home_music":return "設定首頁背景音樂";case "skin":return "切換電視皮膚";case "allow_home":return "家長允許返回電視首頁";case "watch_start":return "啟動答題換觀看時間";case "watch_stop":return "家長結束答題換觀看時間";case "configure":return "套用題庫並開始";case "pause":return "暫停／繼續";case "timer":return "開始倒數";case "lock":return "黑屏上鎖";case "unlock":return "家長解鎖";case "kiosk":return "嚴格模式";default:return s;}}
 void configure(JSONObject b)throws Exception{if(p.getBoolean("watchEnabled",false))throw new Exception("請使用答題換觀看模式的套用按鈕，或先由家長結束該模式");Rules.validate(b,new JSONArray(readAsset()));LearningStartRules.Action start=LearningStartRules.decide(p.getBoolean("locked",false),false,true,owner(),p.getBoolean("strict",false),false);if(start==LearningStartRules.Action.PARENT_LOCK)throw new Exception("目前已由家長上鎖，請先解鎖再開始學習");if(start==LearningStartRules.Action.REQUIRE_PROTECTION)prepareHomeProtection();int subject=b.getInt("subject"),seconds=b.getInt("seconds"),limit=b.getInt("limit");JSONArray topics=b.getJSONArray("topics"),custom=b.getJSONArray("custom");learning.edit().putString("logicLevels",b.optJSONArray("logicLevels")==null?QuestionCatalog.DEFAULT_LEVELS:b.optJSONArray("logicLevels").toString()).putInt("logicCursor",0).putInt("grade",b.optInt("grade",1)).putInt("subject",subject).putInt("seconds",seconds).putInt("limit",limit).putBoolean("voice",b.optBoolean("voice",true)).putString("topics",topics.toString()).putString("custom",custom.toString()).putBoolean("remoteStart",true).commit();MainActivity a=MainActivity.active;if(a!=null&&a.inForeground&&!p.getBoolean("locked",false))a.remoteStart();else startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));}
 String readAsset()throws Exception{java.io.InputStream in=getAssets().open("questions.json");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);in.close();return out.toString("UTF-8");}
 void checkTimer(){if(Rules.expired(p.getBoolean("timer",false),p.getLong("deadlineElapsed",0),p.getLong("deadlineWall",Long.MAX_VALUE),SystemClock.elapsedRealtime(),System.currentTimeMillis()))lock();}
 void lock(){p.edit().putBoolean("locked",true).putBoolean("timer",false).commit();showOverlay();MainActivity a=MainActivity.active;if(a!=null&&a.inForeground)a.applyLockState();else if(owner())try{startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));}catch(Exception ignored){}}
 void unlock(){CuteGuard.close();endManaged();p.edit().putBoolean("locked",false).putBoolean("timer",false).putBoolean("strict",false).putBoolean("watchEnabled",false).commit();hideOverlay();media.resume();MainActivity a=MainActivity.active;if(a!=null){a.playing=false;a.paused=false;a.handler.removeCallbacks(a.tick);a.applyLockState();if(a.inForeground)a.home();}}
 void showOverlay(){if(overlay!=null&&!overlayKind.equals("lock"))hideOverlay();if(overlay!=null||!Settings.canDrawOverlays(this))return;try{LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setGravity(Gravity.CENTER);box.setPadding(40,30,40,30);box.setBackgroundColor(Color.BLACK);TextView title=new TextView(this);title.setText("使用時間已結束\n請由家長手機解鎖");title.setGravity(Gravity.CENTER);title.setTextSize(28);title.setTextColor(Color.WHITE);box.addView(title);Button emergency=new Button(this);emergency.setText("家長緊急復原");box.addView(emergency);emergency.setOnClickListener(v->{if(box.getChildCount()>2)return;EditText input=new EditText(this);input.setHint("輸入家長復原碼");input.setTextColor(Color.WHITE);input.setHintTextColor(Color.GRAY);input.setInputType(129);box.addView(input,new LinearLayout.LayoutParams(600,-2));Button verify=new Button(this);verify.setText("確認家長復原");box.addView(verify);verify.setOnClickListener(w->recovery(input.getText().toString()));input.requestFocus();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(input,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;WindowManager.LayoutParams params=new WindowManager.LayoutParams(-1,-1,type,WindowManager.LayoutParams.FLAG_FULLSCREEN|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON,PixelFormat.OPAQUE);params.gravity=Gravity.FILL;CuteGuard.QuizScroll guarded=new CuteGuard.QuizScroll(this);guarded.setFillViewport(true);guarded.setBackgroundColor(Color.BLACK);guarded.addView(box);wm.addView(guarded,params);overlay=guarded;overlayKind="lock";emergency.requestFocus();}catch(Exception e){p.edit().putString("result","遮罩建立失敗："+e.getClass().getSimpleName()).apply();}}
 public void recovery(String code){try{long until=p.getLong("recoveryBlocked",0);if(System.currentTimeMillis()<until){Toast.makeText(this,"請稍後重試",0).show();return;}if(!Crypto.digest(code.replace(" ","").trim().toUpperCase(java.util.Locale.US)).equals(p.getString("recoveryHash","!"))){int bad=p.getInt("recoveryBad",0)+1;p.edit().putInt("recoveryBad",bad).putLong("recoveryBlocked",bad>=5?System.currentTimeMillis()+30000:0).apply();Toast.makeText(this,"復原碼錯誤",0).show();return;}p.edit().putInt("recoveryBad",0).putLong("recoveryBlocked",0).apply();unlock();p.edit().putString("result","已由家長復原碼解除").commit();}catch(Exception e){}}
 boolean hideOverlay(){if(voiceClips!=null)voiceClips.stop();if(sounds!=null)sounds.stopLoop();if(overlay!=null){try{wm.removeViewImmediate(overlay);}catch(RuntimeException e){if(overlay.isAttachedToWindow()){p.edit().putString("result","遮罩移除失敗："+e.getClass().getSimpleName()).apply();return false;}}overlay=null;}quizToken="";overlayKind="";return true;}
 final Runnable resumePlayback=new Runnable(){public void run(){checkTimer();if(WatchReturn.mayResume(watchPhase(),overlay!=null))media.resume();}};
 long lastWatchReturn=0;
 void resumeViewing(){lastWatchReturn=SystemClock.elapsedRealtime();WatchReturn.reveal(new WatchReturn.Surface(){
 public boolean watching(){checkTimer();return watchPhase()==WatchRules.Phase.WATCHING;}
 public boolean removeCover(){return hideOverlay();}
 public void closeNotice(){CuteGuard.close();}
 public boolean restoreVideo(){MainActivity a=MainActivity.active;return a==null||!a.inForeground||a.returnToWatchVideo();}
 public void releaseAudio(){media.releaseFocus();}
 public void scheduleResume(){h.removeCallbacks(resumePlayback);h.postDelayed(resumePlayback,350);}
 });}


 WatchRules.Phase watchPhase(){return WatchRules.phase(p.getBoolean("locked",false),p.getBoolean("watchEnabled",false),p.getLong("rewardUntil",0),p.getLong("rewardWall",0),p.getInt("rewardBoot",-2),Settings.Global.getInt(getContentResolver(),"boot_count",-1),SystemClock.elapsedRealtime(),System.currentTimeMillis());}
 void endManaged(){if(owner())try{((DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE)).setLockTaskPackages(new ComponentName(this,AdminReceiver.class),new String[]{});}catch(Exception e){}p.edit().putBoolean("strict",false).putBoolean("watchManaged",false).commit();}
 boolean validVideo(String pkg){if(pkg.equals(getPackageName()))return true;if(pkg.isEmpty())return false;try{android.content.pm.PackageManager pm=getPackageManager();Intent home=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME);for(android.content.pm.ResolveInfo ri:pm.queryIntentActivities(home,0))if(ri.activityInfo.packageName.equals(pkg))return false;return pm.getLeanbackLaunchIntentForPackage(pkg)!=null||pm.getLaunchIntentForPackage(pkg)!=null;}catch(Exception e){return false;}}
 JSONArray videoApps(){JSONArray out=new JSONArray();try{out.put(new JSONObject().put("name","YouTube（內建免安裝）").put("package",getPackageName()));android.content.pm.PackageManager pm=getPackageManager();Set<String> seen=new HashSet<String>();for(String category:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER})for(android.content.pm.ResolveInfo ri:pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(category),0)){String pkg=ri.activityInfo.packageName;if(seen.add(pkg)&&validVideo(pkg))out.put(new JSONObject().put("name",ri.loadLabel(pm).toString()).put("package",pkg));if(out.length()>=60)return out;}}catch(Exception e){}return out;}
 void syncOverlay(){WatchRules.Phase phase=watchPhase();if(phase==WatchRules.Phase.PARENT_LOCK){if(p.getBoolean("watchEnabled",false))media.pause();showOverlay();}else if(phase==WatchRules.Phase.QUESTION){h.removeCallbacks(resumePlayback);showQuiz(false);}else if(phase==WatchRules.Phase.WATCHING){if(overlay!=null||(MainActivity.active!=null&&MainActivity.active.inForeground&&SystemClock.elapsedRealtime()-lastWatchReturn>=1000))resumeViewing();}else hideOverlay();}
 public void startWatch(JSONObject b)throws Exception{
 if(!Settings.canDrawOverlays(this))throw new Exception("請先在電視授權顯示在其他應用程式上層");if(p.getBoolean("locked",false))throw new Exception("目前為家長鎖定，請先家長解鎖");boolean managed=b.optBoolean("requireHomeLock",true);String video=b.optString("videoPackage","");if(managed){if(!owner())throw new Exception("尚未啟用裝置擁有者，無法封鎖首頁鍵；請先完成小米電視裝置管理設定");if(Build.VERSION.SDK_INT<28)throw new Exception("嚴格影音模式需要 Android 9 以上");if(!validVideo(video))throw new Exception("請選擇有效的影音 App，不能選電視首頁或邊看邊學");}else if(p.getBoolean("strict",false))throw new Exception("請先家長解鎖退出嚴格模式");
 int seconds=b.optInt("seconds",p.getInt("rewardSeconds",30));WatchRules.rewardDeadline(0,seconds);JSONObject config=b.optJSONObject("config");if(config!=null){Rules.validate(config,new JSONArray(readAsset()));learning.edit().putString("logicLevels",config.optJSONArray("logicLevels")==null?QuestionCatalog.DEFAULT_LEVELS:config.optJSONArray("logicLevels").toString()).putInt("logicCursor",0).putInt("grade",config.optInt("grade",1)).putInt("subject",config.getInt("subject")).putInt("seconds",config.getInt("seconds")).putInt("limit",config.getInt("limit")).putBoolean("voice",config.optBoolean("voice",true)).putString("topics",config.getJSONArray("topics").toString()).putString("custom",config.getJSONArray("custom").toString()).putBoolean("remoteStart",false).commit();}else eligibleQuestions();
 if(managed){DevicePolicyManager dpm=(DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE);ComponentName admin=new ComponentName(this,AdminReceiver.class);dpm.setLockTaskPackages(admin,new String[]{getPackageName(),video});if(Build.VERSION.SDK_INT>=28)dpm.setLockTaskFeatures(admin,DevicePolicyManager.LOCK_TASK_FEATURE_NONE);}p.edit().putBoolean("quizMusic",b.optBoolean("music",true)).putBoolean("quizEffects",b.optBoolean("effects",true)).putInt("quizVolume",Math.max(0,Math.min(100,b.optInt("volume",50)))).putBoolean("strict",managed).putBoolean("watchManaged",managed).putString("watchVideo",video).putBoolean("watchEnabled",true).putInt("rewardSeconds",seconds).putLong("rewardUntil",0).putLong("rewardWall",0).commit();overlayQuestion=null;hideOverlay();MainActivity a=MainActivity.active;if(a!=null&&a.inForeground){a.practiceSounds.stopLoop();a.stopSpeech();a.playing=false;a.handler.removeCallbacks(a.tick);if(a.tts!=null)a.tts.stop();if(!managed)a.moveTaskToBack(true);}if(managed)startActivity(new Intent(this,MainActivity.class).putExtra("managedVideo",video).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));syncOverlay();}
 void stopWatch(){CuteGuard.close();if(!p.getBoolean("locked",false))endManaged();p.edit().putBoolean("watchEnabled",false).commit();overlayQuestion=null;if(p.getBoolean("locked",false)){syncOverlay();return;}hideOverlay();media.resume();}
 JSONArray eligibleQuestions()throws Exception{JSONArray built=new JSONArray(readAsset());JSONArray custom=new JSONArray(learning.getString("custom","[]"));for(int i=0;i<custom.length();i++)built.put(custom.get(i));JSONArray topics=new JSONArray(learning.getString("topics","[\"letters\",\"words\",\"zhuyin\",\"language\",\"math\",\"life\",\"health\",\"logic\",\"custom\"]"));Set<String> selected=new HashSet<String>();for(int i=0;i<topics.length();i++)selected.add(topics.getString(i));Set<String> levels=QuestionCatalog.levels(new JSONArray(learning.getString("logicLevels",QuestionCatalog.DEFAULT_LEVELS)));int subject=learning.getInt("subject",6),grade=learning.getInt("grade",1);JSONArray eligible=new JSONArray();for(int i=0;i<built.length();i++){JSONObject q=built.getJSONObject(i);if(QuestionCatalog.matches(q,subject,grade,selected,levels))eligible.put(q);}if(eligible.length()==0)throw new Exception("目前科目與題型沒有題目，請家長重新設定");return eligible;}
 void showQuiz(boolean sameQuestion){if(overlay!=null&&overlayKind.equals("quiz"))return;if(!Settings.canDrawOverlays(this)){p.edit().putString("result","上層顯示權限已撤銷，無法顯示答題遮罩").apply();return;}hideOverlay();try{if(!sameQuestion||overlayQuestion==null){JSONArray choices=eligibleQuestions();int pick=new SecureRandom().nextInt(choices.length());String last=p.getString("lastWatchQuestion","");if(choices.length()>1&&choices.getJSONObject(pick).optString("question").equals(last))pick=(pick+1)%choices.length();if(choices.getJSONObject(pick).optString("topic").equals("logic")){ArrayList<Integer> ids=new ArrayList<Integer>();for(int j=0;j<choices.length();j++)ids.add(j);int sequential=QuestionCatalog.nextLogicIndex(choices,ids,learning.getInt("logicCursor",0));if(sequential>=0)pick=sequential;}overlayQuestion=choices.getJSONObject(pick);if(overlayQuestion.optString("topic").equals("logic"))learning.edit().putInt("logicCursor",overlayQuestion.optInt("logicNumber",0)).commit();p.edit().putString("lastWatchQuestion",overlayQuestion.optString("question")).apply();}final String token=UUID.randomUUID().toString();quizToken=token;WatchOverlay ui=new WatchOverlay(this,new WatchOverlay.Callback(){public void correct(JSONObject q,String choice){if(!token.equals(quizToken))return;checkTimer();if(p.getBoolean("locked",false)||!p.getBoolean("watchEnabled",false))return;sounds.correct();recordWatch(q,choice,true);int seconds=p.getInt("rewardSeconds",30);p.edit().putLong("rewardUntil",WatchRules.rewardDeadline(SystemClock.elapsedRealtime(),seconds)).putLong("rewardWall",System.currentTimeMillis()+seconds*1000L).putInt("rewardBoot",Settings.Global.getInt(getContentResolver(),"boot_count",-1)).commit();overlayQuestion=null;resumeViewing();Toast.makeText(TvService.this,"答對了！可以繼續看 "+seconds+" 秒",Toast.LENGTH_SHORT).show();}
 public void wrong(JSONObject q,String choice){if(token.equals(quizToken)){sounds.wrong();recordWatch(q,choice,false);}}
 public void read(JSONObject q){readWatchQuestion(q);}
 public void recover(String code){recovery(code);}
 public void back(){hideOverlay();showQuiz(true);}});
 View box=ui.create(overlayQuestion,p.getInt("rewardSeconds",30));int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;WindowManager.LayoutParams params=new WindowManager.LayoutParams(-1,-1,type,WindowManager.LayoutParams.FLAG_FULLSCREEN|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON,PixelFormat.OPAQUE);wm.addView(box,params);overlay=box;overlayKind="quiz";watchAnswerTimer.start(SystemClock.elapsedRealtime());if(!((PowerManager)getSystemService(POWER_SERVICE)).isInteractive())watchAnswerTimer.pause(SystemClock.elapsedRealtime());media.pause();sounds.startLoop();readWatchQuestion(overlayQuestion);
 }catch(Exception e){p.edit().putString("result","答題遮罩建立失敗："+e.getMessage()).apply();p.edit().putBoolean("locked",true).commit();showOverlay();}}
 void readWatchQuestion(JSONObject q){if(learning.getBoolean("voice",true)&&!voiceClips.play(q.optString("question"),null))voiceClips.play("請選擇正確的答案",null);}
 void recordWatch(JSONObject q,String choice,boolean good){try{JSONObject item=new JSONObject();item.put("time",System.currentTimeMillis());item.put("q",q.optString("question"));item.put("chosen",choice);item.put("answer",q.optString("answer"));item.put("good",good);item.put("mode","watch");item.put("topic",q.optString("topic"));item.put("elapsedMs",watchAnswerTimer.elapsed(SystemClock.elapsedRealtime()));studyHistory.append(item);watchAnswerTimer.reset(SystemClock.elapsedRealtime());p.edit().putInt("watchAttempts",p.getInt("watchAttempts",0)+1).putInt("watchCorrect",p.getInt("watchCorrect",0)+(good?1:0)).commit();}catch(Exception e){Toast.makeText(this,"作答紀錄儲存失敗",Toast.LENGTH_SHORT).show();}}


